"use strict";

const PRODUCTS = [
  {
    id: "1-key",
    name: "1-Key Clicker",
    price: 2.49,
    image: "data:image/webp;base64,",
    badge: "Pocket pick",
    description: "One compact mechanical key for quick, satisfying clicks anywhere."
  },
  {
    id: "2-key",
    name: "2-Key Clicker",
    price: 3.99,
    image: "data:image/webp;base64,",
    badge: "Easy rhythm",
    description: "A two-key pair that stays portable while giving your fingers more variety."
  },
  {
    id: "3-key",
    name: "3-Key Clicker",
    price: 4.99,
    image: "data:image/webp;base64,",
    badge: "Fan favorite",
    description: "Three mechanical keys in a balanced row for a fuller fidget pattern."
  },
  {
    id: "4-key",
    name: "4-Key Clicker",
    price: 7.49,
    image: "data:image/webp;base64,",
    badge: "Maximum clicks",
    description: "Four keys for the biggest tactile setup in the standard clicker lineup."
  }
];

const STORAGE_KEY = "fidgetClickerCartV1";
const CHECKOUT_URL = ""; // Paste a hosted Stripe/PayPal/Square checkout URL here when ready.

let cart = loadCart();
let toastTimer;

const productGrid = document.getElementById("productGrid");
const cartDrawer = document.getElementById("cartDrawer");
const cartOverlay = document.getElementById("cartOverlay");
const cartItems = document.getElementById("cartItems");
const cartCount = document.getElementById("cartCount");
const cartSubtotal = document.getElementById("cartSubtotal");
const openCartButton = document.getElementById("openCartButton");
const shopCartButton = document.getElementById("shopCartButton");
const closeCartButton = document.getElementById("closeCartButton");
const clearCartButton = document.getElementById("clearCartButton");
const checkoutButton = document.getElementById("checkoutButton");
const checkoutModal = document.getElementById("checkoutModal");
const checkoutSummary = document.getElementById("checkoutSummary");
const checkoutMessage = document.getElementById("checkoutMessage");
const copyOrderButton = document.getElementById("copyOrderButton");
const closeCheckoutButton = document.getElementById("closeCheckoutButton");
const toast = document.getElementById("toast");

function loadCart() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (!saved || typeof saved !== "object") return {};

    return Object.fromEntries(
      Object.entries(saved)
        .filter(([id, quantity]) => PRODUCTS.some((product) => product.id === id) && Number.isInteger(quantity) && quantity > 0)
    );
  } catch {
    return {};
  }
}

function saveCart() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(cart));
}

function formatMoney(amount) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD"
  }).format(amount);
}

function getProduct(productId) {
  return PRODUCTS.find((product) => product.id === productId);
}

function cartEntries() {
  return Object.entries(cart)
    .map(([id, quantity]) => ({ product: getProduct(id), quantity }))
    .filter((entry) => entry.product && entry.quantity > 0);
}

function cartItemCount() {
  return cartEntries().reduce((sum, entry) => sum + entry.quantity, 0);
}

function cartTotal() {
  return cartEntries().reduce((sum, entry) => sum + (entry.product.price * entry.quantity), 0);
}

function renderProducts() {
  productGrid.innerHTML = PRODUCTS.map((product) => `
    <article class="product-card">
      <div class="product-image">
        <img src="${product.image}" alt="${product.name}">
        <span class="product-badge">${product.badge}</span>
      </div>
      <div class="product-info">
        <h3>${product.name}</h3>
        <p>${product.description}</p>
        <div class="product-row">
          <span class="price">${formatMoney(product.price)}</span>
          <button class="button primary add-button" type="button" data-add-product="${product.id}">Add to cart</button>
        </div>
      </div>
    </article>
  `).join("");

  const byId = Object.fromEntries(PRODUCTS.map((product) => [product.id, product]));
  const miniMix = byId["1-key"].price + byId["2-key"].price;
  const clickCrew = PRODUCTS.reduce((sum, product) => sum + product.price, 0);
  document.getElementById("miniMixPrice").textContent = formatMoney(miniMix);
  document.getElementById("clickCrewPrice").textContent = formatMoney(clickCrew);
}

function renderCart() {
  const entries = cartEntries();
  cartCount.textContent = String(cartItemCount());
  cartSubtotal.textContent = formatMoney(cartTotal());
  checkoutButton.disabled = entries.length === 0;
  checkoutButton.style.opacity = entries.length === 0 ? ".5" : "1";
  checkoutButton.style.cursor = entries.length === 0 ? "not-allowed" : "pointer";

  if (entries.length === 0) {
    cartItems.innerHTML = `
      <div class="empty-cart">
        <div>
          <div style="font-size:2.4rem; margin-bottom:8px;" aria-hidden="true">🛒</div>
          <strong>Your cart is ready for clicks.</strong>
          <span>Add a fidget from the shop and it will appear here.</span>
        </div>
      </div>
    `;
    return;
  }

  cartItems.innerHTML = entries.map(({ product, quantity }) => `
    <article class="cart-item">
      <img class="cart-thumb" src="${product.image}" alt="">
      <div>
        <h3>${product.name}</h3>
        <div class="cart-item-price">${formatMoney(product.price)} each</div>
        <div class="quantity" aria-label="Quantity for ${product.name}">
          <button type="button" data-qty-product="${product.id}" data-qty-delta="-1" aria-label="Decrease ${product.name} quantity">−</button>
          <span>${quantity}</span>
          <button type="button" data-qty-product="${product.id}" data-qty-delta="1" aria-label="Increase ${product.name} quantity">+</button>
        </div>
      </div>
      <button class="remove-button" type="button" data-remove-product="${product.id}">Remove</button>
    </article>
  `).join("");
}

function addToCart(productId, quantity = 1) {
  if (!getProduct(productId)) return;
  const safeQuantity = Math.max(1, Number(quantity) || 1);
  cart[productId] = (cart[productId] || 0) + safeQuantity;
  saveCart();
  renderCart();
  showToast(`${getProduct(productId).name} added to cart`);
}

function updateQuantity(productId, delta) {
  if (!cart[productId]) return;
  const nextQuantity = cart[productId] + Number(delta);

  if (nextQuantity <= 0) {
    delete cart[productId];
  } else {
    cart[productId] = Math.min(nextQuantity, 99);
  }

  saveCart();
  renderCart();
}

function removeFromCart(productId) {
  if (!cart[productId]) return;
  delete cart[productId];
  saveCart();
  renderCart();
  showToast("Item removed");
}

function clearCart() {
  cart = {};
  saveCart();
  renderCart();
  showToast("Cart cleared");
}

function addBundle(bundleName) {
  const bundleIds = bundleName === "all-four"
    ? ["1-key", "2-key", "3-key", "4-key"]
    : ["1-key", "2-key"];

  bundleIds.forEach((id) => {
    cart[id] = (cart[id] || 0) + 1;
  });

  saveCart();
  renderCart();
  openCart();
  showToast(bundleName === "all-four" ? "Click Crew added" : "Mini Mix added");
}

function openCart() {
  cartDrawer.classList.add("open");
  cartOverlay.classList.add("open");
  cartDrawer.setAttribute("aria-hidden", "false");
  cartOverlay.setAttribute("aria-hidden", "false");
  openCartButton.setAttribute("aria-expanded", "true");
  document.body.style.overflow = "hidden";
  closeCartButton.focus();
}

function closeCart() {
  cartDrawer.classList.remove("open");
  cartOverlay.classList.remove("open");
  cartDrawer.setAttribute("aria-hidden", "true");
  cartOverlay.setAttribute("aria-hidden", "true");
  openCartButton.setAttribute("aria-expanded", "false");
  document.body.style.overflow = "";
}

function buildOrderSummary() {
  const lines = cartEntries().map(({ product, quantity }) =>
    `${quantity} × ${product.name} — ${formatMoney(product.price * quantity)}`
  );
  lines.push(``, `Subtotal: ${formatMoney(cartTotal())}`);
  return lines.join("\n");
}

function beginCheckout() {
  if (cartItemCount() === 0) return;

  if (CHECKOUT_URL.trim()) {
    window.location.href = CHECKOUT_URL;
    return;
  }

  checkoutSummary.textContent = buildOrderSummary();
  checkoutMessage.innerHTML = "Your cart is ready. Add a hosted payment link to <code>CHECKOUT_URL</code> in <code>app.js</code> to send customers to a real payment page.";
  checkoutModal.classList.add("open");
  closeCart();
  closeCheckoutButton.focus();
}

async function copyOrderSummary() {
  const summary = buildOrderSummary();
  try {
    await navigator.clipboard.writeText(summary);
    showToast("Order summary copied");
  } catch {
    const textarea = document.createElement("textarea");
    textarea.value = summary;
    document.body.appendChild(textarea);
    textarea.select();
    document.execCommand("copy");
    textarea.remove();
    showToast("Order summary copied");
  }
}

function closeCheckout() {
  checkoutModal.classList.remove("open");
}

function showToast(message) {
  clearTimeout(toastTimer);
  toast.textContent = message;
  toast.classList.add("show");
  toastTimer = setTimeout(() => toast.classList.remove("show"), 1800);
}

productGrid.addEventListener("click", (event) => {
  const button = event.target.closest("[data-add-product]");
  if (!button) return;
  addToCart(button.dataset.addProduct);
});

cartItems.addEventListener("click", (event) => {
  const quantityButton = event.target.closest("[data-qty-product]");
  if (quantityButton) {
    updateQuantity(quantityButton.dataset.qtyProduct, Number(quantityButton.dataset.qtyDelta));
    return;
  }

  const removeButton = event.target.closest("[data-remove-product]");
  if (removeButton) removeFromCart(removeButton.dataset.removeProduct);
});

document.querySelectorAll(".bundle-add").forEach((button) => {
  button.addEventListener("click", () => addBundle(button.dataset.bundle));
});

document.getElementById("builderAddButton").addEventListener("click", () => {
  const chosenId = document.getElementById("builderKeys").value;
  addToCart(chosenId);
  openCart();
});

openCartButton.addEventListener("click", openCart);
shopCartButton.addEventListener("click", openCart);
closeCartButton.addEventListener("click", closeCart);
cartOverlay.addEventListener("click", closeCart);
clearCartButton.addEventListener("click", clearCart);
checkoutButton.addEventListener("click", beginCheckout);
copyOrderButton.addEventListener("click", copyOrderSummary);
closeCheckoutButton.addEventListener("click", closeCheckout);
checkoutModal.addEventListener("click", (event) => {
  if (event.target === checkoutModal) closeCheckout();
});

document.addEventListener("keydown", (event) => {
  if (event.key !== "Escape") return;
  if (checkoutModal.classList.contains("open")) closeCheckout();
  else if (cartDrawer.classList.contains("open")) closeCart();
});

renderProducts();
renderCart();


const heroProductImage = document.getElementById("heroProductImage");
if (heroProductImage) heroProductImage.src = PRODUCTS[3].image;
